    [Fact]
    public async Task ReturnReviewerSeesOriginalCapturedInstallationSeparatelyFromCurrentRelationships()
    {
        // Controlled recorded report/closure and current native facts; actual component/state rendering, not browser acceptance.
        var start=WorkOrderExecutionStartStateTests.QualifiedStart();var original=start.Review.Prerequisites.Requirements;
        var submitted=Beep.OilandGas.ApiService.Tests.WorkOrderExecutionStartFixture.Submission(database:original.Context.Database,originalOrder:original.Order,taskOverride:original.Approval.Permit.Task,qualifiedWorkAssets:start.Review.QualifiedWorkAssets);
        var report=CompanyWorkOrderSubmissionFacts.From(submitted.Command.Prepare(DateTime.UtcNow));var context=original.Context with{ActorUserId="return-approver",Revision="current-return-evidence"};
        var closure=new CompanyMaintenanceClosureFacts(context.Company,context.Database,report.Query,context.ActorUserId,"FacilityRole","closed-history",["closed-task"],DateTime.UtcNow,new string('A',64),new string('B',64),report.Revision,new string('C',64));
        var current=report.QualifiedWorkAssets! with{Context=context,ComparedAtUtc=DateTime.UtcNow,Equipment=report.QualifiedWorkAssets!.Equipment.Select(row=>row with{Installation=row.Installation with{InstallationObservation=8,NativeRevision=new string('E',64)}}).ToArray()};
        var compared=DateTime.UtcNow;var order=submitted.Command.Review.Inspections.Current.Order;
        var review=new CompanyMaintenanceAssetEvidence(context,report,closure,order,[],compared,CompanyMaintenanceAssetEvidence.GetBlockers(context,report,closure,order,[],compared,current)){QualifiedAssets=current};review.Require();
        using var company=Company(review);var fields=new Mock<IFieldSelectionContext>();fields.Setup(value=>value.GetCurrentFieldIdAsync()).ReturnsAsync(context.FieldId);
        var client=new Mock<ICompanyMaintenanceHandoffClient>();client.Setup(value=>value.ReadMaintenanceAssetEvidenceAsync(report.Query,It.IsAny<CancellationToken>())).ReturnsAsync(review);
        var services=new ServiceCollection();services.AddLogging();services.AddMudServices();services.AddSingleton(company);services.AddScoped<MaintenanceAssetEvidenceState>();services.AddSingleton(client.Object);services.AddSingleton(fields.Object);services.AddSingleton<AuthenticationStateProvider>(new Auth(context.ActorUserId));services.AddSingleton<IJSRuntime,NoBrowser>();services.AddSingleton<IComponentActivator,Components>();services.AddSingleton(new OilGasCallFailures(Mock.Of<IFailureReporter>()));
        await using var provider=services.BuildServiceProvider();await using var renderer=new HtmlRenderer(provider,provider.GetRequiredService<ILoggerFactory>());
        await renderer.Dispatcher.InvokeAsync(async()=>
        {
            var root=await renderer.RenderComponentAsync<MaintenanceAssetEvidencePanel>(ParameterView.FromDictionary(new Dictionary<string,object?>{{"Query",report.Query}}));var panel=((Components)provider.GetRequiredService<IComponentActivator>()).Panel;
            await (Task)panel.GetType().GetMethod("ReadAsync",BindingFlags.Instance|BindingFlags.NonPublic)!.Invoke(panel,null)!;await Task.Yield();var html=System.Net.WebUtility.HtmlDecode(root.ToHtmlString());
            Assert.Contains("Original work-start asset scope",html);Assert.Contains("Original equipment pump",html);Assert.Contains("observation 7",html);Assert.Contains("Current qualified facility and equipment relationships",html);Assert.Contains("observation 8",html);
            Assert.Contains("current scope cannot amend the recorded work",html);Assert.DoesNotContain(submitted.Command.Reason,html);
        });
        client.Verify(value=>value.RecordMaintenanceAssetReturnAsync(It.IsAny<CompanyMaintenanceAssetReturnCommand>(),It.IsAny<CancellationToken>()),Times.Never);
    }
    [Fact]
    public void ExistingWellOnlyAssetsKeepTheOriginalJsonShapeAndDigest()
    {
        var review=Review(MaintenanceClosureStateTests.Review("original-well",assetReturn:true));var legacyJson=System.Text.Json.JsonSerializer.Serialize(new{review.Context,review.Report,review.Closure,review.Order,review.Wells,review.ComparedAtUtc,review.Blockers});
        Assert.Equal(legacyJson,System.Text.Json.JsonSerializer.Serialize(review));Assert.DoesNotContain("QualifiedAssets",legacyJson);
        var legacyDigest=ProcessDefinitionRevision.FromJson(System.Text.Json.JsonSerializer.Serialize(new{review.Context,review.Report,review.Closure,review.Order,Wells=review.Wells.OrderBy(row=>row.WellId,StringComparer.Ordinal).Select(row=>row.SourceRevision()),review.Blockers}));Assert.Equal(legacyDigest,review.SourceRevision());
        var restored=System.Text.Json.JsonSerializer.Deserialize<CompanyMaintenanceAssetEvidence>(legacyJson)!;restored.Require();Assert.Null(restored.QualifiedAssets);Assert.Equal(legacyDigest,restored.SourceRevision());
    }
    internal static CompanyMaintenanceAssetEvidence Review(CompanyMaintenanceClosureReview? original=null,bool writable=false)
    {
        // Coherent already-recorded UI source seam; original component scope precedes every fixture decision.
        var review=original??MaintenanceClosureStateTests.Review("original-well");var saved=MaintenanceClosureStateTests.Recorded(new(review,Guid.NewGuid(),"Private original closure",true));var closure=CompanyMaintenanceClosureFacts.From(saved);var source=review.Current.Completion;var context=source.Context;var now=DateTime.UtcNow;
        var rows=new[]{("Life Cycle","Operating"),("Role","Produce"),("Condition","Shut In")}.Select(value=>new CompanyWellReturnFacet("original-well","recorded-source",value.Item1+"-key",value.Item1,value.Item2,null,null,"Y",now.AddDays(-1),null,null,"Asia/Kuwait",true,new string('D',64))).ToArray();
        var references=rows.Select(value=>new CompanyWellReturnReference(value.Facet,value.Value,"Y",null,null,true,new string('E',64))).Append(new("Condition","Active","Y",null,null,true,new string('F',64))).ToArray();
        var level=writable?"WRITE":"READ";var well=new CompanyMaintenanceWellEvidence(context,"original-well",context.FieldId!,context.Company.BusinessAssociateId,level,new string('A',64),"Asia/Kuwait",new string('B',64),rows,references,now,CompanyMaintenanceWellEvidence.GetBlockers(context,"original-well",context.FieldId!,context.Company.BusinessAssociateId,level,new string('A',64),"Asia/Kuwait",new string('B',64),rows,references,now));var utc=DateTime.UtcNow;
        var result=new CompanyMaintenanceAssetEvidence(context,source.Report,closure,source.Order,[well],utc,CompanyMaintenanceAssetEvidence.GetBlockers(context,source.Report,closure,source.Order,[well],utc));result.Require();return result;
    }
